#include <cstddef>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <new>
#include <vector>

std::size_t g_allocs = 0;  // the counting operator new from the lesson on allocations
std::size_t g_bytes = 0;
void* operator new(std::size_t n) {
    ++g_allocs;
    g_bytes += n;
    if (void* p = std::malloc(n)) {
        return p;
    }
    throw std::bad_alloc{};
}
void operator delete(void* p) noexcept { std::free(p); }

struct Matrix {
    std::size_t rows, cols;
    std::vector<double> data;  // row after row, in one block
    Matrix(std::size_t r, std::size_t c) : rows(r), cols(c), data(r * c, 0.0) {}
    double& operator()(std::size_t i, std::size_t j) { return data[i * cols + j]; }
    double operator()(std::size_t i, std::size_t j) const { return data[i * cols + j]; }
};

int main() {
    g_allocs = 0;
    g_bytes = 0;
    std::vector<std::vector<double>> nested(1000, std::vector<double>(50));
    std::cout << "vector of vectors: " << g_allocs << " allocations, " << g_bytes << " bytes\n";
    g_allocs = 0;
    g_bytes = 0;
    Matrix flat(1000, 50);
    std::cout << "one Matrix: " << g_allocs << " allocation, " << g_bytes << " bytes\n";
    std::cout << "row 3 starts " << &flat(3, 0) - &flat(0, 0) << " doubles in\n";

    // price change per unit of each position (columns) in each scenario (rows)
    Matrix moves(3, 4);
    const double values[] = {-2.0, 1.5, -0.5, 3.0,
                             4.0, -1.0, 0.25, -6.0,
                             -8.0, -3.0, -1.0, 2.0};
    for (std::size_t k = 0; k < 12; ++k) {
        moves.data[k] = values[k];
    }
    const double position[] = {100, -200, 400, 50};

    std::cout << std::fixed << std::setprecision(2);
    for (std::size_t i = 0; i < moves.rows; ++i) {
        double pnl = 0.0;
        for (std::size_t j = 0; j < moves.cols; ++j) {
            pnl += moves(i, j) * position[j];
        }
        std::cout << "scenario " << i << " P&L " << pnl << '\n';
    }
    return 0;
}

