#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

struct Matrix {
    std::size_t rows, cols;
    std::vector<double> data;
    Matrix(std::size_t r, std::size_t c) : rows(r), cols(c), data(r * c, 0.0) {}
    double& operator()(std::size_t i, std::size_t j) { return data[i * cols + j]; }
    double operator()(std::size_t i, std::size_t j) const { return data[i * cols + j]; }
};

// swapped loops: the inner loop walks a row of b and a row of c, side by side
Matrix multiply_ikj(const Matrix& a, const Matrix& b) {
    const std::size_t n = a.rows;
    Matrix c(n, n);
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t k = 0; k < n; ++k) {
            const double aik = a(i, k);
            for (std::size_t j = 0; j < n; ++j) {
                c(i, j) += aik * b(k, j);
            }
        }
    }
    return c;
}

// tiles of B x B: for each tile of b, sweep every row of a while the tile is hot
Matrix multiply_blocked(const Matrix& a, const Matrix& b, std::size_t B) {
    const std::size_t n = a.rows;  // assumes n is a multiple of B
    Matrix c(n, n);
    for (std::size_t kk = 0; kk < n; kk += B) {
        for (std::size_t jj = 0; jj < n; jj += B) {
            for (std::size_t i = 0; i < n; ++i) {
                for (std::size_t k = kk; k < kk + B; ++k) {
                    const double aik = a(i, k);
                    for (std::size_t j = jj; j < jj + B; ++j) {
                        c(i, j) += aik * b(k, j);
                    }
                }
            }
        }
    }
    return c;
}

double checksum(const Matrix& m) {
    double s = 0.0;
    for (double x : m.data) {
        s += x;
    }
    return s;
}

int main() {
    const std::size_t n = 256;
    Matrix a(n, n), b(n, n);
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = 0; j < n; ++j) {
            a(i, j) = ((i * 7 + j * 3) % 11) * 0.1 - 0.3;
            b(i, j) = ((i * 5 + j * 2) % 13) * 0.07 - 0.4;
        }
    }
    const Matrix c1 = multiply_ikj(a, b);
    const Matrix c2 = multiply_blocked(a, b, 64);
    std::cout << std::fixed << std::setprecision(6) << std::boolalpha;
    std::cout << "ikj checksum " << checksum(c1) << '\n';
    std::cout << "blocked checksum " << checksum(c2) << '\n';
    std::cout << "same bits: " << (c1.data == c2.data) << '\n';
    return 0;
}

