#include <cmath>
#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

struct Matrix {
    std::size_t rows, cols;
    std::vector<double> data;
    Matrix(std::size_t r, std::size_t c) : rows(r), cols(c), data(r * c, 0.0) {}
    double& operator()(std::size_t i, std::size_t j) { return data[i * cols + j]; }
    double operator()(std::size_t i, std::size_t j) const { return data[i * cols + j]; }
};

// returns: one row per day, one column per asset. The result is assets x assets.
Matrix covariance(const Matrix& returns) {
    const std::size_t days = returns.rows, n = returns.cols;
    std::vector<double> mean(n, 0.0);
    for (std::size_t t = 0; t < days; ++t) {
        for (std::size_t i = 0; i < n; ++i) {
            mean[i] += returns(t, i);
        }
    }
    for (double& m : mean) {
        m /= days;
    }
    Matrix cov(n, n);
    for (std::size_t t = 0; t < days; ++t) {        // one pass over the days, row by row
        for (std::size_t i = 0; i < n; ++i) {
            for (std::size_t j = i; j < n; ++j) {   // the upper triangle only
                cov(i, j) += (returns(t, i) - mean[i]) * (returns(t, j) - mean[j]) / (days - 1);
            }
        }
    }
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = 0; j < i; ++j) {
            cov(i, j) = cov(j, i);                   // mirror: cov is symmetric
        }
    }
    return cov;
}

int main() {
    Matrix returns(8, 3);  // daily returns of a stock, a second stock, and a bond fund
    returns.data = {0.012, 0.010, -0.002, -0.008, -0.011, 0.003, 0.004, 0.006, 0.001,
                    -0.015, -0.012, 0.004, 0.009, 0.007, -0.001, 0.002, -0.001, 0.000,
                    -0.006, -0.004, 0.002, 0.011, 0.013, -0.003};
    const Matrix cov = covariance(returns);
    std::cout << std::fixed << std::setprecision(3) << "correlation\n";
    for (std::size_t i = 0; i < 3; ++i) {
        for (std::size_t j = 0; j < 3; ++j) {
            std::cout << std::setw(8) << cov(i, j) / std::sqrt(cov(i, i) * cov(j, j));
        }
        std::cout << '\n';
    }
    const double w[3] = {0.5, 0.3, 0.2};  // portfolio weights
    double var = 0.0, weighted_vols = 0.0;
    for (std::size_t i = 0; i < 3; ++i) {
        weighted_vols += w[i] * std::sqrt(cov(i, i) * 252);
        for (std::size_t j = 0; j < 3; ++j) {
            var += w[i] * cov(i, j) * w[j];
        }
    }
    std::cout << std::setprecision(2) << "portfolio annual vol " << 100 * std::sqrt(var * 252)
              << "%, weighted average of the vols " << 100 * weighted_vols << "%\n";
    return 0;
}

