#include <vector>

struct Matrix {
    std::size_t rows, cols;
    std::vector<double> data;
    Matrix(std::size_t r, std::size_t c) : rows(r), cols(c), data(r * c, 0.0) {}
    double& operator()(std::size_t i, std::size_t j) { return data[i * cols + j]; }
    double operator()(std::size_t i, std::size_t j) const { return data[i * cols + j]; }
};

// lower-triangular L with L * L^T == a, or nothing when a isn't positive definite
std::optional<Matrix> cholesky(const Matrix& a) {
    const std::size_t n = a.rows;
    Matrix L(n, n);
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = 0; j <= i; ++j) {
            double s = a(i, j);
            for (std::size_t k = 0; k < j; ++k) {
                s -= L(i, k) * L(j, k);
            }
            if (i == j) {
                if (s <= 0.0) return std::nullopt;  // no real square root: not a valid correlation
                L(i, i) = std::sqrt(s);
            } else {
                L(i, j) = s / L(j, j);
            }
        }
    }
    return L;
}

void print(const Matrix& m) {
    for (std::size_t i = 0; i < m.rows; ++i) {
        for (std::size_t j = 0; j < m.cols; ++j) {
            std::cout << std::setw(9) << m(i, j);
        }
        std::cout << '\n';
    }
}

int main() {
    Matrix corr(3, 3);
    corr.data = {1.0, 0.6, 0.3,
                 0.6, 1.0, 0.5,
                 0.3, 0.5, 1.0};
    const std::optional<Matrix> L = cholesky(corr);
    std::cout << std::fixed << std::setprecision(4) << "L\n";
    print(*L);

    double worst = 0.0;  // rebuild L * L^T and compare
    for (std::size_t i = 0; i < 3; ++i) {
        for (std::size_t j = 0; j < 3; ++j) {
            double s = 0.0;
            for (std::size_t k = 0; k < 3; ++k) {
                s += (*L)(i, k) * (*L)(j, k);
            }
            worst = std::max(worst, std::abs(s - corr(i, j)));
        }
    }
    std::cout << "largest error in L * L^T: " << std::scientific << std::setprecision(1) << worst << '\n';

    Matrix bad(3, 3);  // A and B move together, A and C too, yet B and C move apart
    bad.data = {1.0, 0.9, 0.9,
                0.9, 1.0, -0.9,
                0.9, -0.9, 1.0};
    std::cout << "inconsistent matrix: " << (cholesky(bad) ? "factored" : "not positive definite") << '\n';
    return 0;
}

#include <algorithm>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <random>

double norm_cdf(double x) { return 0.5 * std::erfc(-x / std::sqrt(2.0)); }

double bs_call(double S, double K, double r, double sigma, double T) {
    const double sd = sigma * std::sqrt(T);
    const double d1 = (std::log(S / K) + (r + 0.5 * sigma * sigma) * T) / sd;
    return S * norm_cdf(d1) - K * std::exp(-r * T) * norm_cdf(d1 - sd);
}

int main() {
    const double S1 = 100.0, S2 = 100.0, v1 = 0.20, v2 = 0.30, T = 1.0;
    const int paths = 200000;
    const double rhos[] = {0.9, 0.0, -0.5};
    std::cout << std::fixed << std::setprecision(4);
    for (double rho : rhos) {
        std::mt19937_64 rng(42);                        // the same seed for every rho
        std::normal_distribution<double> gauss(0.0, 1.0);
        double sxy = 0.0, sxx = 0.0, syy = 0.0, payoff = 0.0;
        for (int p = 0; p < paths; ++p) {
            const double z1 = gauss(rng);
            const double z2 = gauss(rng);
            const double x1 = z1;                                         // row 0 of L
            const double x2 = rho * z1 + std::sqrt(1.0 - rho * rho) * z2;  // row 1 of L
            const double a = S1 * std::exp(-0.5 * v1 * v1 * T + v1 * std::sqrt(T) * x1);
            const double b = S2 * std::exp(-0.5 * v2 * v2 * T + v2 * std::sqrt(T) * x2);
            payoff += std::max(a - b, 0.0);
            sxy += x1 * x2;
            sxx += x1 * x1;
            syy += x2 * x2;
        }
        const double spread_vol = std::sqrt(v1 * v1 + v2 * v2 - 2.0 * rho * v1 * v2);
        std::cout << "rho " << std::setw(7) << rho << ": sample corr " << std::setw(7) << sxy / std::sqrt(sxx * syy)
                  << ", swap option " << payoff / paths << " simulated, "
                  << bs_call(S1, S2, 0.0, spread_vol, T) << " formula\n";
    }
    return 0;
}

